import unittest
from candidate import decode_shift

class TestDecodeShift(unittest.TestCase):
    def test_decode_shift_normal_case_lowercase(self):
        self.assertEqual(decode_shift("fghij"), "abcde")

    def test_decode_shift_normal_case_uppercase(self):
        self.assertEqual(decode_shift("FGHIJ"), "ABCDE")

    def test_decode_shift_mixed_case(self):
        self.assertEqual(decode_shift("FgHiJ"), "AbCdE")

    def test_decode_shift_with_spaces(self):
        self.assertEqual(decode_shift("fgh ij"), "abc de")

    def test_decode_shift_with_numbers(self):
        with self.assertRaises(TypeError):
            decode_shift("123abc")

    def test_decode_shift_empty_string(self):
        self.assertEqual(decode_shift(""), "")

    def test_decode_shift_single_char_lowercase(self):
        self.assertEqual(decode_shift("f"), "a")

    def test_decode_shift_single_char_uppercase(self):
        self.assertEqual(decode_shift("F"), "A")

    def test_decode_shift_wraparound_lowercase(self):
        self.assertEqual(decode_shift("zabc"), "abc")

    def test_decode_shift_wraparound_uppercase(self):
        self.assertEqual(decode_shift("ZABC"), "ABC")

    def test_decode_shift_wraparound_mixed(self):
        self.assertEqual(decode_shift("Zabc"), "ABC")

    def test_decode_shift_none_input(self):
        with self.assertRaises(TypeError):
            decode_shift(None)

    def test_decode_shift_non_string_input(self):
        with self.assertRaises(TypeError):
            decode_shift(123)

    def test_decode_shift_multiple_shifts(self):
        self.assertEqual(decode_shift("fghijklmnopqrstuvwxyz"), "abcdefghijklmnopqrstuvwxyz")

    def test_decode_shift_case_preservation(self):
        self.assertEqual(decode_shift("ABCDEFGHIJKLMNOPQRSTUVWXYZ"), "FGHIJKLMNOPQRSTUVWXYZABCDE")

    def test_decode_shift_preserves_non_alphabetic(self):
        with self.assertRaises(TypeError):
            decode_shift("fgh!@#")

    def test_decode_shift_preserves_numbers_in_encoded(self):
        with self.assertRaises(TypeError):
            decode_shift("123abc")

    def test_decode_shift_preserves_special_characters(self):
        with self.assertRaises(TypeError):
            decode_shift("fgh!@#abc")

if __name__ == '__main__':
    unittest.main()
